 63 | function canCompleteMelds(counts, remaining) {
 64 |   if (remaining === 0) return true;
 65 |   const first = [...counts.keys()].filter(tile => counts.get(tile) > 0).sort((a, b) => {
 66 |     const x = tileInfo(a); const y = tileInfo(b); return x.suit.localeCompare(y.suit) || x.rank - y.rank;
 67 |   })[0];
 68 |   if (!first) return false;
 69 |   const count = counts.get(first);
 70 |   if (count >= 3) {
 71 |     counts.set(first, count - 3);
 72 |     if (canCompleteMelds(counts, remaining - 3)) { counts.set(first, count); return true; }
 73 |     counts.set(first, count);
 74 |   }
