 85 | /** A winning concealed portion is four melds plus a pair after accounting for exposed melds. */
 86 | export function isWinningHand(tiles, exposedMelds = 0) {
 87 |   if (!Array.isArray(tiles) || !Number.isInteger(exposedMelds) || exposedMelds < 0 || exposedMelds > 4 || !tiles.every(isTileCode)) return false;
