 89 |   if (tiles.length !== needed) return false;
 90 |   const counts = countsFor(tiles);
 91 |   if ([...counts.values()].some(count => count > 4)) return false;
 92 |   for (const [tile, count] of counts) {
 93 |     if (count < 2) continue;
 94 |     counts.set(tile, count - 2);
 95 |     if (canCompleteMelds(counts, needed - 2)) { counts.set(tile, count); return true; }
 96 |     counts.set(tile, count);
 97 |   }
 98 |   return false;
 99 | }
