101 | export function canRon(hand, discard, exposedMelds = 0) {
102 |   return isWinningHand([...hand, discard], exposedMelds);
103 | }
104 | 
105 | export function canPon(hand, discard) { return hand.filter(tile => tile === discard).length >= 2; }
