123 | export function legalClaims(hand, discard, isNextPlayer, exposedMelds = 0) {
124 |   return { ron: canRon(hand, discard, exposedMelds), pon: canPon(hand, discard), chi: isNextPlayer ? chiOptions(hand, discard) : [] };
125 | }
