137 | export function removeTiles(hand, tiles) {
138 |   const next = [...hand];
139 |   for (const tile of tiles) {
140 |     const index = next.indexOf(tile);
141 |     if (index < 0) throw new Error(`Tile ${tile} is not in hand.`);
142 |     next.splice(index, 1);
143 |   }
144 |   return next;
145 | }

